-- Settings
INSERT OR REPLACE INTO settings (key, value) VALUES
  ('site_name_ar', 'سرايا الألمنيوم'),
  ('site_name_en', 'Saraya Aluminum'),
  ('tagline_ar', 'شركة سعودية متخصصة في تصنيع وتركيب أعمال الألمنيوم والزجاج بأعلى معايير الجودة، نخدم القطاعات السكنية والتجارية والحكومية.'),
  ('phone', '+966 55 000 0000'),
  ('whatsapp', '966550000000'),
  ('email', 'info@saraya-aluminum.com'),
  ('address_ar', 'الرياض - حي المصانع - طريق الخرج'),
  ('working_hours_ar', 'السبت - الخميس: 8 صباحاً - 6 مساءً'),
  ('about_ar', 'سرايا الألمنيوم شركة سعودية رائدة في مجال تصنيع وتركيب أعمال الألمنيوم والزجاج، تأسست لتقديم حلول متكاملة تجمع بين الجودة العالمية والذوق العصري. نمتلك مصنعاً حديثاً مجهزاً بأحدث خطوط الإنتاج، وفريقاً هندسياً وفنياً بخبرة تتجاوز 15 عاماً. نفخر بتنفيذ مئات المشاريع السكنية والتجارية والحكومية في مختلف مناطق المملكة، ونلتزم في كل مشروع بالدقة في المواعيد وجودة الخامات وضمان ما بعد التركيب.'),
  ('instagram', 'https://instagram.com/saraya.aluminum');

