-- Products
INSERT OR IGNORE INTO products (slug, name_ar, short_desc_ar, description_ar, category_id, main_image, specs, colors, featured, is_new, status, sort_order) VALUES
  ('sliding-window-thermal', 'نافذة سحب عازلة (ثيرمال بريك)', 'نافذة ألمنيوم سحب بنظام عزل حراري كامل وزجاج دبل', 'نافذة سحب بقطاعات ألمنيوم ثيرمال بريك عازلة للحرارة والصوت، زجاج دبل 6+12+6 مم، مناسبة للمناخ السعودي وتخفض استهلاك التكييف حتى 30%. تأتي بمجاري مقاومة للأتربة وسيور EPDM ألمانية.', 1, 'https://images.unsplash.com/photo-1509644851169-2acc08aa25b5?w=800&q=80', '[{"label":"نوع القطاع","value":"ثيرمال بريك 2.0 مم"},{"label":"الزجاج","value":"دبل 6+12+6 مم"},{"label":"العزل الصوتي","value":"حتى 38 ديسيبل"},{"label":"الضمان","value":"10 سنوات"}]', '["أبيض","أسود","رمادي","بني خشبي"]', 1, 1, 'published', 1),
  ('hinged-window', 'نافذة مفصلية (قلاب)', 'نافذة مفصلية بفتحات متعددة الاتجاهات وإغلاق محكم', 'نافذة مفصلية بنظام فتح قلاب علوي أو جانبي، إغلاق متعدد النقاط لإحكام تام ضد الأتربة، خيارات زجاج سادة أو عاكس.', 1, 'https://images.unsplash.com/photo-1416331108676-a22ccb276e35?w=800&q=80', '[{"label":"نوع الفتح","value":"قلاب / مفصلي"},{"label":"الإغلاق","value":"متعدد النقاط"},{"label":"الضمان","value":"5 سنوات"}]', '["أبيض","أسود","شامبين"]', 1, 0, 'published', 2),
  ('main-entrance-door', 'باب مدخل رئيسي فاخر', 'باب ألمنيوم مدخل رئيسي بتصميم حديث وأمان عالي', 'باب مدخل رئيسي بقطاع ألمنيوم معزز، حشوات عزل، أقفال أمان متعددة النقاط، خيارات تصميم بشرائح خشبية أو زجاج مسنفر.', 2, 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&q=80', '[{"label":"السماكة","value":"70 مم"},{"label":"القفل","value":"5 نقاط أمان"},{"label":"الضمان","value":"10 سنوات"}]', '["أسود","بني","رمادي غامق"]', 1, 0, 'published', 3),
  ('sliding-door', 'باب سحب بانورامي', 'باب سحب زجاجي بانورامي بمساحات زجاج واسعة', 'باب سحب بانورامي بقطاعات نحيفة تعطي إطلالة زجاجية واسعة، عجلات تحمل حتى 200 كجم للدرفة، انزلاق سلس وصامت.', 2, 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?w=800&q=80', '[{"label":"تحمل الدرفة","value":"حتى 200 كجم"},{"label":"الزجاج","value":"دبل / سيكوريت"},{"label":"الضمان","value":"10 سنوات"}]', '["أسود","رمادي","أبيض"]', 1, 1, 'published', 4),
  ('curtain-wall-structural', 'واجهة ستركشر زجاجية', 'واجهة زجاجية ستركشر بدون كباس ظاهر', 'نظام واجهات ستركشر بمظهر زجاجي كامل بدون قطاعات ظاهرة، زجاج عاكس أو دبل بألوان متعددة، مناسب للأبراج والمعارض.', 3, 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', '[{"label":"النظام","value":"Structural Glazing"},{"label":"الزجاج","value":"عاكس دبل 24 مم"},{"label":"التثبيت","value":"هيكل ألمنيوم مخفي"}]', '["أزرق عاكس","فضي","دخاني"]', 1, 0, 'published', 5),
  ('curtain-wall-classic', 'واجهة كرتن وول كلاسيك', 'واجهة كرتن وول بكباسات ظاهرة أنيقة', 'نظام كرتن وول تقليدي بكباسات ألمنيوم ظاهرة، الخيار الأكثر اقتصادية للمباني التجارية والإدارية مع متانة عالية.', 3, 'https://images.unsplash.com/photo-1554435493-93422e8220c8?w=800&q=80', '[{"label":"النظام","value":"Stick System"},{"label":"عرض الكباس","value":"50 مم"},{"label":"الزجاج","value":"دبل عاكس"}]', '["فضي","أسود","برونزي"]', 0, 0, 'published', 6),
  ('aluminum-kitchen-modern', 'مطبخ ألمنيوم مودرن', 'مطبخ ألمنيوم كامل مقاوم للرطوبة والحرارة', 'مطبخ ألمنيوم عصري بخامات إيطالية، مقاوم 100% للرطوبة والصدأ، أرفف داخلية قابلة للتعديل، مفصلات تحميل ثقيل ألمانية، تفصيل حسب المقاس.', 4, 'https://images.unsplash.com/photo-1556909212-d5b604d0c90d?w=800&q=80', '[{"label":"الخامة","value":"ألمنيوم + HPL"},{"label":"المفصلات","value":"Blum ألمانية"},{"label":"الضمان","value":"15 سنة"}]', '["أبيض لامع","رمادي مطفي","خشبي"]', 1, 0, 'published', 7),
  ('glass-handrail', 'درابزين زجاج سيكوريت', 'درابزين زجاجي شفاف بتثبيت ألمنيوم أنيق', 'درابزين زجاج سيكوريت 10 مم بقاعدة ألمنيوم U-Channel، مظهر عصري نظيف للأدراج الداخلية والبلكونات، مطابق لاشتراطات السلامة.', 5, 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?w=800&q=80', '[{"label":"الزجاج","value":"سيكوريت 10-12 مم"},{"label":"التثبيت","value":"U-Channel ألمنيوم"},{"label":"الارتفاع","value":"90-110 سم"}]', '["شفاف","دخاني","مسنفر"]', 1, 0, 'published', 8),
  ('movable-pergola', 'برجولا ألمنيوم متحركة', 'برجولا بشرائح متحركة كهربائياً مع تحكم ريموت', 'برجولا ألمنيوم بشرائح متحركة بمحرك كهربائي وريموت كنترول، تتحكم بالإضاءة والتهوية، مقاومة للأمطار مع مجاري تصريف مدمجة، إضاءة LED اختيارية.', 6, 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=800&q=80', '[{"label":"التشغيل","value":"محرك كهربائي + ريموت"},{"label":"الشرائح","value":"ألمنيوم 0-120 درجة"},{"label":"إضافات","value":"إضاءة LED، حساس مطر"}]', '["أبيض","رمادي","أسود"]', 1, 1, 'published', 9),
  ('electric-shutter', 'شتر كهربائي', 'شتر ألمنيوم كهربائي بعزل ورغوة داخلية', 'شتر ألمنيوم كهربائي بشرائح محشوة برغوة بولي يوريثان للعزل الحراري، محرك صامت مع ريموت، خاصية الأمان ضد الاحتجاز.', 7, 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?w=800&q=80', '[{"label":"الشرائح","value":"55 مم معزولة"},{"label":"المحرك","value":"Somfy فرنسي"},{"label":"التشغيل","value":"ريموت + يدوي طوارئ"}]', '["أبيض","بيج","رمادي"]', 0, 0, 'published', 10),
  ('shower-box-luxury', 'كبينة استحمام فاخرة', 'كبينة زجاج سيكوريت 8 مم بإكسسوارات نحاس مطلي', 'كبينة استحمام زجاج سيكوريت 8 مم مقاوم للكسر، إكسسوارات نحاس مطلي ضد الصدأ، طلاء نانو ضد ترسبات الماء، تفصيل حسب المقاس.', 8, 'https://images.unsplash.com/photo-1620626011761-996317b8d101?w=800&q=80', '[{"label":"الزجاج","value":"سيكوريت 8 مم"},{"label":"الإكسسوارات","value":"نحاس مطلي"},{"label":"الطلاء","value":"نانو ضد الترسبات"}]', '["شفاف","مسنفر","دخاني"]', 1, 0, 'published', 11),
  ('mosquito-net', 'شبك حماية ومنيوم', 'شبك ناموسية ألمنيوم بأنظمة سحب وثابت', 'شبك ناموسية بإطار ألمنيوم، خيارات سحب جانبي أو رول علوي أو ثابت، شبك فايبر جلاس لا يصدأ، سهل الفك والتركيب للتنظيف.', 1, 'https://images.unsplash.com/photo-1416331108676-a22ccb276e35?w=800&q=80', '[{"label":"الشبك","value":"فايبر جلاس"},{"label":"الأنظمة","value":"سحب / رول / ثابت"}]', '["أبيض","أسود","رمادي"]', 0, 0, 'published', 12);

-- Services
INSERT OR IGNORE INTO services (slug, title_ar, short_desc_ar, description_ar, icon, features_ar, sort_order) VALUES
  ('consultation', 'استشارة ورفع مقاسات مجاني', 'زيارة موقعك ورفع المقاسات وتقديم الاستشارة الفنية مجاناً', 'يزورك فريقنا الفني في الموقع لرفع المقاسات بدقة بأجهزة ليزر، وتقديم استشارة فنية شاملة حول أفضل الأنظمة والخامات المناسبة لمشروعك وميزانيتك، مع عرض عينات حية للقطاعات والألوان.', 'fa-ruler-combined', '["زيارة مجانية داخل المدينة","رفع مقاسات بأجهزة ليزر","عرض عينات حية","استشارة فنية بدون التزام"]', 1),
  ('manufacturing', 'تصنيع حسب الطلب', 'تصنيع دقيق في مصنعنا بأحدث خطوط الإنتاج', 'نصنع جميع منتجاتنا في مصنعنا الخاص بأحدث ماكينات القص والتجميع CNC، مما يضمن دقة المقاسات وجودة التشطيب وسرعة التسليم، مع فحص جودة لكل قطعة قبل الخروج من المصنع.', 'fa-industry', '["ماكينات CNC حديثة","خامات أوروبية معتمدة","فحص جودة شامل","التزام بمواعيد التسليم"]', 2),
  ('installation', 'تركيب احترافي', 'فرق تركيب مدربة بإشراف هندسي كامل', 'فرق تركيب متخصصة ومدربة على أعلى مستوى، بإشراف مهندسين ذوي خبرة، نلتزم بمعايير السلامة ونظافة الموقع، وتسليم الأعمال جاهزة بدون أي ملاحظات.', 'fa-helmet-safety', '["فرق مدربة ومعتمدة","إشراف هندسي","التزام بمعايير السلامة","تنظيف الموقع بعد التركيب"]', 3),
  ('maintenance', 'صيانة وضمان', 'ضمان يصل 15 سنة وخدمة صيانة دورية', 'نقدم ضماناً حقيقياً موثقاً يصل إلى 15 سنة حسب المنتج، مع خدمة صيانة دورية وقطع غيار أصلية متوفرة دائماً، وفريق صيانة يصلك خلال 48 ساعة.', 'fa-screwdriver-wrench', '["ضمان موثق حتى 15 سنة","قطع غيار أصلية","استجابة خلال 48 ساعة","عقود صيانة سنوية"]', 4);

-- Projects
INSERT OR IGNORE INTO projects (slug, title_ar, description_ar, cover_image, client, location, project_type, project_date, featured, sort_order) VALUES
  ('riyadh-villa-narjes', 'فيلا سكنية - حي النرجس', 'تنفيذ كامل أعمال الألمنيوم لفيلا فاخرة: نوافذ ثيرمال بريك، أبواب سحب بانورامية، درابزين زجاجي، وبرجولا متحركة للحديقة الخلفية. المشروع نُفذ خلال 45 يوماً بمساحة زجاج تتجاوز 400 م².', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=1000&q=80', 'عميل خاص', 'الرياض - حي النرجس', 'residential', '2025', 1, 1),
  ('jeddah-tower-facade', 'برج تجاري - واجهة كرتن وول', 'تصميم وتنفيذ واجهة كرتن وول ستركشر بمساحة 2,800 م² لبرج تجاري من 12 طابقاً، زجاج عاكس أزرق دبل مع فتحات تهوية مخفية وأبواب مداخل أوتوماتيكية.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1000&q=80', 'شركة تطوير عقاري', 'جدة - طريق الملك', 'commercial', '2024', 1, 2),
  ('riyadh-school-project', 'مجمع مدارس حكومي', 'توريد وتركيب 320 نافذة ألمنيوم و85 باباً لمجمع مدارس حكومي، مع شبك حماية وشتر يدوي لجميع الفصول، وفق المواصفات الحكومية المعتمدة.', 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=1000&q=80', 'وزارة التعليم', 'الرياض', 'governmental', '2024', 1, 3),
  ('dammam-compound', 'كمباوند سكني - الدمام', 'أعمال ألمنيوم متكاملة لكمباوند سكني من 24 فيلا: نوافذ، أبواب، مطابخ ألمنيوم، وكبائن استحمام لجميع الوحدات مع توحيد التصميم والألوان.', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?w=1000&q=80', 'شركة إسكان', 'الدمام', 'residential', '2023', 1, 4),
  ('riyadh-mall-storefronts', 'واجهات محلات مول تجاري', 'تنفيذ واجهات زجاجية لـ 46 محلاً تجارياً داخل مول، زجاج سيكوريت 12 مم مع أبواب أوتوماتيكية وإطارات ألمنيوم أسود مطفي.', 'https://images.unsplash.com/photo-1519567241046-7f570eee3ce6?w=1000&q=80', 'إدارة المول', 'الرياض', 'commercial', '2023', 0, 5),
  ('qassim-villa-pergola', 'برجولات ومظلات استراحة', 'تصميم وتركيب برجولات ألمنيوم متحركة بمساحة 180 م² لاستراحة خاصة، مع إضاءة LED مدمجة وحساسات مطر أوتوماتيكية.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=1000&q=80', 'عميل خاص', 'القصيم', 'residential', '2025', 0, 6);

-- Home hero slides
INSERT OR IGNORE INTO home_sections (section_type, title_ar, subtitle_ar, image, cta_text_ar, cta_link, sort_order) VALUES
  ('hero', 'حلول ألمنيوم متكاملة بجودة عالمية', 'من التصميم إلى التركيب، نصنع لك نوافذ وأبواباً وواجهات تجمع بين الأناقة والمتانة وعزل يوفر في فاتورة الكهرباء', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=1600&q=80', 'اطلب عرض سعر', '/quote', 1),
  ('hero', 'مصنعنا.. سر جودتنا', 'خطوط إنتاج CNC حديثة وخامات أوروبية معتمدة وفحص جودة لكل قطعة قبل التسليم', 'https://images.unsplash.com/photo-1565043666747-69f6646db940?w=1600&q=80', 'تعرف على خدماتنا', '/services', 2),
  ('hero', 'ضمان حقيقي حتى 15 سنة', 'نقف خلف منتجاتنا بضمان موثق وخدمة صيانة تصلك خلال 48 ساعة', 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=1600&q=80', 'شاهد مشاريعنا', '/projects', 3);

