INSERT OR IGNORE INTO why_us_items (icon, title_ar, description_ar, sort_order) VALUES
  ('fa-award', 'خبرة +15 سنة', 'خبرة تراكمية في تصنيع وتركيب أعمال الألمنيوم لمئات المشاريع', 1),
  ('fa-industry', 'مصنع خاص', 'مصنع مجهز بأحدث ماكينات CNC يضمن الدقة وسرعة التسليم', 2),
  ('fa-shield-halved', 'ضمان حتى 15 سنة', 'ضمان موثق على المنتجات والتركيب مع خدمة ما بعد البيع', 3),
  ('fa-gem', 'خامات أوروبية', 'قطاعات وإكسسوارات معتمدة من أفضل المصادر العالمية', 4),
  ('fa-clock', 'التزام بالمواعيد', 'جدول زمني واضح لكل مشروع ونلتزم به حتى التسليم', 5),
  ('fa-tags', 'أسعار تنافسية', 'تسعير مباشر من المصنع بدون وسطاء', 6);
